      throw new Error(`File tidak ditemukan di path: ${filePath}`);
    }

    const dataBuffer = fs.readFileSync(filePath);
    const data = await pdf(dataBuffer);

    // Kembalikan teks bersih hasil ekstraksi
    return data.text;
  } catch (error) {
    console.error(`\n[PDF Error] Gagal membaca atau mengekstrak PDF: ${error.message}`);
    return "";
  }
}

module.exports = {
  extractTextFromPDF
};
